132	    /**
133	     * Estrapolo dalla configurazione alcune informazioni
134	     * valorizzandole come proprietà del componente.
135	     */
136	    protected function parseConfig()
137	    {
138	        $config = $this->config;
139	
140	        // regole di default per validazione
141	        if (!array_key_exists('rules', $config)) {
142	            $config['rules'] = $this->defaultRules();
143	        }
144	
145	
146	        // eventuali campi aggiuntivi
147	        $this->langFields = array_key_exists('lang_fields', $config) ? $config['lang_fields'] : [];
148	        $this->fields = array_key_exists('fields', $config) ? $config['fields'] : [];
149	
150	        // memorizzo lista locales e id corrente
151	        $this->currentLgId = current(array_keys($this->langList));
152	
153	        // aggiorno alcune informazioni per assecondare vista
154	        //$this->file->values_tmp = $this->file->values;
155	        $this->fieldsValues = $this->file->values;
156	        foreach ($this->file->langs as $k => $rsLang) {
157	            $this->langFieldsValues[$rsLang->lang] = $rsLang->values;
158	        }
159	
