167	    public function updatedLangFieldsValues($value, $name)
168	    {
169	        //pulizia del valore in ingresso
170	        $purifier = app()->make(Purifier::class, [$this->functionCode]);
171	        $value = $purifier->clean($value);
172	
173	        $nameCp = explode('.', $name);
