223	    /**
224	     * Caricamento di un nuovo file.
225	     * Può avvenire per un file nuovo non ancora confermato
226	     * o per un file precedentemente caricato e confermato.
227	     */
228	    public function updatedFileUpload()
229	    {
230	        // validazione
231	        $this->validate([
232	            'file_upload' => $this->config['rules'],
233	        ], [
234	            'file_upload.mimes' => 'Il file non è consentito. Sono ammessi: ' . $this->allowedMimes($this->config) . '.',
235	        ], [
236	            'file_upload' => 'Il file'
237	        ]);
238	
239	
240	        // memorizzo nuovo file
241	        $path = $this->file_upload->getPath() . '/' . $this->file_upload->getFilename();
242	
243	        try {
244	            $url = str_replace(url('/'), '', $this->file_upload->temporaryUrl());
245	        } catch (Throwable $e) {
246	            $url = '';
247	        }
248	
249	        // salvo
250	        $g = Gallery::findOrFail($this->file->id);
251	        $g->image_new = json_encode([
252	            'name' => $this->file_upload->getClientOriginalName(),
253	            'path' => $path,
254	            'url' => $url,
255	        ]);
256	        $g->created_token = $this->createdToken;
257	        $g->save();
258	
259	        $this->file = $g;
260	    }
