263	    /**
264	     * Annulla sostituzione del file.
265	     * Eseguito solo per file già caricati e confermati
266	     * precedentemente.
267	     */
268	    public function undoFileReplace()
269	    {
270	        if ($this->file->status != 'Y') {
271	            abort(404);
272	        }
273	
274	        $this->resetValidation();
275	        $this->file->image_new = null;
276	        $this->file->save();
