306	    /**
307	     * Evento emesso da parent al cambio della modalità
308	     * di ordinamento
309	     * (on/off)
310	     */
311	    public function refreshOrderingStatus(bool $newStatus)
312	    {
313	        $this->parentOrdering = $newStatus;
314	    }
