316	    /**
317	     * Render
318	     */
319	    public function render()
320	    {
321	        /**
322	         * Se non ho file (es. in seguito a cancellazione)
323	         * ritorno stringa vuota.
324	         */
325	        if ($this->file === null) {
326	            return '<div></div>';
327	        }
328	
329	
330	        /**
331	         * mostro didascalia in caso stia ordinando.
332	         * Se ho campi in lingua, recupero il primo campo nella prima lingua,
333	         * altrimenti primo campo non in lingua
334	         */
335	        $this->orderingCaption = '';
336	        if ($this->parentOrdering) :
337	
338	            $this->orderingCaption = '-';
339	
340	        if ($this->langFields) {
341	            $firstField = current($this->langFields)['name'];
342	            $firstLang = current($this->langFieldsValues);
343	            if (!empty($firstLang[$firstField])) {
344	                $this->orderingCaption = $firstLang[$firstField];
345	            }
346	        } elseif ($this->fields) {
347	            $firstField = current($this->fields)['name'];
348	
349	            if (!empty($this->fieldsValues[$firstField])) {
350	                $this->orderingCaption = $this->fieldsValues[$firstField];
351	            }
352	        }
353	
354	        $this->orderingCaption = Str::words($this->orderingCaption, 5);
355	        endif;
356	
357	
358	        /**
359	         * Aggiorno proprietà sul file corrente prima di andare in output
360	         */
361	        $imageNew = json_decode($this->file->image_new);
362	        $this->file->url = Storage::disk('public')->url($this->file->url);
363	        if ($imageNew) {
364	            $this->file->url = $imageNew->url;
365	            $this->file->path = $imageNew->url;
366	            $this->file->name = $imageNew->name;
367	        }
368	
369	        View::addLocation(__DIR__ . '/../../../resources/views/components');
370	
371	        return view('file_input_file', []);
372	    }
373	
374	
375	    /**
376	     * Refresh della configurazione (quando sono in input widget)
377	     * Al selettore di una nuova tipologia o al load, viene inviata la nuova
378	     * configurazione specifica per la tipologia, per uniformare le logiche.
379	     * Poichè l'array in ingresso contiene tutti i campi file usati da quel widget (es. img_1, img_2, etc..), dobbiamo
380	     * estrarre dalla configurazione passata la configurazione specifica per quel campo. (es. img_1)
381	     *
382	     * @param array $newConfig la configurazione della nuova tipologia di widget (comprensiva di tutti i campi!)
383	     */
384	    public function updateWidgetConfig(array $selectedWidgetConfig)
385	    {
386	        // Se la configurazione passata non contiene il campo corrente, non faccio niente.
387	        // Tutti i campi vengono notificati, (tutte le n immagini del widget), ma non è detto che la configurazione
388	        // in ingresso contenga la configurazione per questo campo.
389	        if (!array_key_exists($this->name, $selectedWidgetConfig)) {
390	            return;
391	        }
392	
393	        // aggiorno la configurazione
394	        $this->config = $selectedWidgetConfig[$this->name];
395	
396	        // reparsing per valorizzare altre proprietà che mi servono nel render
397	        $this->parseConfig();
398	    }
399	}
