34	    public function __construct(Gallery $image = null, $extraAttributes = [], $tag = 'img', $config = null, $lazy = false)
35	    {
36	        $this->image = $image;
37	        $this->extraAttributes = $extraAttributes;
38	        $this->tag = $tag;
39	
40	        // global flag "disableLazyload" must be set on false
41	        $this->lazy = (bool)$lazy && self::$disableLazyload === false;
42	
43	        // se non ho passato chiave di configurazione, uso quella tra le informazioni del record Gallery
44	        $this->configKey = $config;
