55	    public function render()
56	    {
57	        $file = $this->image;
58	
59	        if (!$file) {
60	            return '';
61	        }
62	
63	        // recupera la configurazione di marvin per il file richiesto
64	        $config = config('marvin.functions.' . $this->configKey);
65	
66	        // controllo su chiave size per evitare errori (es. widget 3 img_mobi non viene caricata ma presente per alcuni widget più vecchi)
67	        if (!isset($config['size'])) {
68	            return '';
69	        }
70	
71	
72	
73	
74	        // Costruisco srcset.
75	        // Ciclo le taglie impostate in configurazione, ma mando in output.
76	        // La dimensione reale del file, in modo che siano corrette se la configurazione
77	        // è stata aggiornata in seguito o se le immagini sono state caricate più piccole.
78	        $src = [];
79	        $srcset = [];
80	        $dimensions = [];
81	        $defaultSrc = null;
82	        if ($file) {
83	            foreach ($config['size'] as $prefix => $size) {
84	
85	                $info = pathinfo($file->url);
86	
87	                // tento di recuperare info sull'immagine, se fallisce, salto la taglia
88	                try {
89	                    $getImageSize = getimagesize(Storage::disk("public")->path($info["dirname"] . '/' . $prefix . $info["basename"]));
90	
91	                    // lancio eccezione manualmente per gestire entrambe possibilità in unico punto
92	                    if ($getImageSize === false) {
93	                        throw new Exception('Error getting image info []'.$info["dirname"] . '/' . $prefix . $info["basename"]);
94	                    }
95	                } catch (Exception $e) {
96	                    continue;
97	                }
98	
99	                $key = rtrim($prefix, '_');
100	
101	                // memorizzo url di questa taglia
102	                $src[$key] = Storage::disk("public")->url($info["dirname"] . '/' . $prefix . $info["basename"]);
103	
104	                // costruisco e memorizzo elemento del srcset con la larghezza reale dell'immagine
105	                $srcset[$key] = $src[$key] . ' ' . $getImageSize[0] . 'w';
106	
107	                // memorizzo dimensioni reali
108	                $dimensions[$key] = [$getImageSize[0], $getImageSize[1]];
109	
110	                if (!$defaultSrc) {
111	                    $defaultSrc = $src[$key];
112	                }
113	            }
114	        }
115	
116	
117	        // esplodo attributi extra
118	        $extraAttributes = [];
119	        foreach ($this->extraAttributes as $key => $value) {
120	            $extraAttributes[$key] = $key . '="' . $value . '"';
121	        }
122	
123	        // recupero testo alternativo
124	        if ($file->current_lang->values && array_key_exists('alt_tag', $file->current_lang->values)) {
125	            $extraAttributes['alt'] = ' alt="'.$file->current_lang->values['alt_tag'].'"';
126	        }
127	
128	        // se ho richiesto il lazy load
129	        if ($this->lazy === true) {
130	            // rimpiazzo attribuito sizes con data-sizes
131	            if (array_key_exists('sizes', $extraAttributes)) {
132	                $extraAttributes['sizes'] = str_replace('sizes', 'data-sizes', $extraAttributes['sizes']);
133	            }
134	
135	            // img vs source
136	            switch ($this->tag):
137	                // in caso di "source" non ho classe lazy
138	                case 'source':
139	                    return '<source data-srcset="' . implode(',', $srcset) . '" ' . implode(' ', $extraAttributes) . '>';
140	                case 'img':
141	                    if (empty($src['P']) && empty($src['S'])) {
142	                        return '';
143	                    }
144	                    // se width/height sono stati passati dall'esterno, li usa già $extraAttributes;
145	                    // altrimenti calcola dal primo size non-placeholder
146	                    if (isset($this->extraAttributes['width']) || isset($this->extraAttributes['height'])) {
147	                        $sizeAttribs = '';
148	                    } else {
149	                        $dimKey = null;
150	                        foreach ($dimensions as $k => $v) {
151	                            // recupero la prima dimensione non-placeholder
152	                            if ($k !== 'P') {
153	                                $dimKey = $k;
154	                                break;
155	                            }
156	                        }
157	                        $dimKey = $dimKey ?? (isset($dimensions['P']) ? 'P' : null);
158	                        $sizeAttribs = ($dimKey && isset($dimensions[$dimKey]))
159	                            ? ' width="' . $dimensions[$dimKey][0] . '" height="' . $dimensions[$dimKey][1] . '"'
160	                            : '';
161	                    }
162	                    return '<img class="lazyload loading"  src="' . ($src['P'] ?? $src['S']) . '"  data-srcset="' . implode(',', $srcset) . '"' . $sizeAttribs . ' ' . implode(' ', $extraAttributes) . '>';
163	            endswitch;
164	        }
165	
166	        // rimuovo la taglia placeholder dall'output senza lazy load
167	        if (array_key_exists('P', $src) && count($src) > 1) {
168	            unset($src['P']);
169	            $defaultSrc = current($src);
170	        }
171	
172	        // aggiunge width/height solo per tag img
173	        $sizeAttribs = '';
174	        if ($this->tag === 'img') {
175	            // se width/height sono stati passati dall'esterno, li usa già $extraAttributes
176	            if (!isset($this->extraAttributes['width']) && !isset($this->extraAttributes['height'])) {
177	                $defaultKey = $defaultSrc ? array_search($defaultSrc, $src) : null;
178	                if ($defaultKey !== false && isset($dimensions[$defaultKey])) {
179	                    $sizeAttribs = ' width="' . $dimensions[$defaultKey][0] . '" height="' . $dimensions[$defaultKey][1] . '"';
180	                }
181	            }
182	        }
183	
184	        // output senza lazy load
185	        return '<' . $this->tag . ' src="' . $defaultSrc . '" srcset="' . implode(',', $srcset) . '"' . $sizeAttribs . ' ' . implode(' ', $extraAttributes) . '>';
186	    }
