<?php

namespace Italamp\OnPage\Models;

use Exception;
use OnPage\Thing;
use OnPage\Resource;
use Illuminate\Database\Eloquent\Model;
use Italamp\OnPage\Jobs\SaveRemoteImage;
use Illuminate\Database\Eloquent\Builder;

trait OnPageTrait
{
    /**
     * Recupero elemento sulla base della corrispondenza locale
     */
    public function scopeByOnPage(Builder $query, $remoteResourceName, $remoteId)
    {
        return $query->where([
            ['onpage_resource', $remoteResourceName],
            ['onpage_id', $remoteId],
        ]);
    }


    /**
     * First or new di un elemento mappato su uno remoto
     */
    public static function firstOrNewByOnPage($remoteResourceName, $remoteId)
    {
        $model = self::firstOrNew([
            'onpage_resource' => $remoteResourceName,
            'onpage_id' => $remoteId,
        ]);

        // disabilitato di default
        if (!$model->id) {
            $model->public = 'N';
        }

        return $model;
    }

    /**
     * Collect Thing properties into array
     */
    public function collectFields(Thing $thing, Resource $resource, $serialize = false, $excludeFields = [])
    {
        $data = [];

        foreach ($resource->fields() as $field) {
            if ($field->is_translatable === true || in_array($field->name, $excludeFields)) {
                continue;
            }

            $data[$field->name] = (array)$field;


            $data[$field->name]['value'] = $thing->val($field->name);
        }

        return $serialize !== true ? $data : json_encode($data);
    }


    /**
     * Collect tranlatable Thing fields (filtered by locale) into array
     */
    protected function collectTranslatableFields(Model $localItemLang, string $locale, Thing $thing, Resource $resource, $serialize = false)
    {
        $data = [];

        foreach ($resource->fields() as $field) {
            if ($field->is_translatable === false) {
                continue;
            }

            $data[$field->name] = [
                'name' => $field->name,
                'label' => $field->label,
                'type' => $field->type,
                'is_multiple' => $field->is_multiple,
                'is_translatable' => $field->is_translatable,
            ];

            $data[$field->name]['value'] = $thing->val($field->name, $locale);
        }


        return $serialize !== true ? $data : json_encode($data);
    }



    /**
     * Mutator for onpage_raw
     */
    public function setOnpageRawAttribute($value)
    {
        $this->attributes['onpage_raw'] = json_encode($value);
    }


    /**
     * Accessor for onpage_raw
     */
    public function getOnpageRawAttribute($value)
    {
        return json_decode($this->attributes['onpage_raw'], true);
    }


    /**
     * Check if there's a value for a remote file
     * and returns it
     */
    public function hasFile($remoteFileName, $langId = null): mixed
    {
        // get lang model if requested
        $model = $langId ? $this->langs->where('lang', $langId)->first() : $this;

        // cast to array if needed
        $onpageRaw = is_array($model->onpage_raw) ? $model->onpage_raw : json_decode($model->onpage_raw, true);

        if (!array_key_exists($remoteFileName, $onpageRaw)) {
            return false;
        }

        $remoteValue = $onpageRaw[$remoteFileName]['value'];

        if ($remoteValue === null || !is_array($remoteValue)) {
            return false;
        }

        return $remoteValue;
    }


    /**
     * Default mapping of remote fields to local ones
     * (use this in children classes method onPageUpdateFromRemote)
     */
    public function onPageUpdateDefault(Thing $remoteItem, Resource $remoteResource, $excludeFields = []): self
    {
        $this->onpage_resource = $remoteResource->name;
        $this->onpage_id = $remoteItem->id;
        $this->onpage_raw = $this->collectFields($remoteItem, $remoteResource, false, $excludeFields);

        return $this;
    }


    /**
     * Routine for dispatching job to retrieve remote files
     * @param array $remoteFilesList list of remote file keys to sync
     * @param array $config Marvin's function config
     */
    public function onPageSyncFiles(array $remoteFilesList, array $config, $force = false)
    {
        foreach ($remoteFilesList as $remoteFileName) :

            // get specific file config from marvin config
            $fileConfig = array_filter($config, function ($item) use ($remoteFileName) {
                return
                    is_array($item)
                    && array_key_exists('onpage_name', $item)
                    && $item['onpage_name'] == $remoteFileName;
            });
            if (!$fileConfig) {
                throw new Exception("Configuration for remote file [$remoteFileName] does not exist.");
            }
            $localFileName = array_keys($fileConfig)[0];
            $fileConfig = current($fileConfig);

            // File is translatable
            // Check if there is a remote corresponding file for each locale before actually dispatching job
            if ($fileConfig['onpage_translatable'] === true) {
                foreach (app()->LangManager->getLocales() as  $langId => $localeInfo) {
                    if ($this->hasFile($remoteFileName, $langId) === false) {
                        continue;
                    }

                    SaveRemoteImage::dispatch($this, $config, $remoteFileName, $localFileName, $localeInfo[0], $force);
                }

                continue;
            }

            // File is not translatable
            // Check if there is a remote value for corresponding remote file, before actually dispatching job
            if ($this->hasFile($remoteFileName) === false) {
                continue;
            }

            SaveRemoteImage::dispatch($this, $config, $remoteFileName, $localFileName, null, $force);

        endforeach;
    }
